package com.jmadsen.dashhop;
import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.TextUtils;
/** Updates only this fixed utility. Never requests a service redraw or recreates the shortcut strip. */
final class AudioDockItem extends LinearLayout implements AudioSessionRepository.Listener {
 final AudioSessionRepository audio;final TextView info,icon;final boolean vertical;final int maxLength;final HorizontalScrollView horizontal;final ScrollView scroll;final java.util.function.BooleanSupplier touched;final Runnable retry=this::changed;
 AudioDockItem(Context c,int fg,boolean v,int max,HorizontalScrollView hs,ScrollView vs,java.util.function.BooleanSupplier activeTouch){super(c);touched=activeTouch;vertical=v;maxLength=max;horizontal=hs;scroll=vs;audio=AudioSessionRepository.get(c);setGravity(Gravity.CENTER);setOrientation(HORIZONTAL);setPadding(4,2,4,2);icon=new TextView(c);icon.setText("♫");icon.setTextColor(fg);icon.setTextSize(24);icon.setGravity(Gravity.CENTER);addView(icon,new LayoutParams(DockController.px(c,32),-1));info=new TextView(c);info.setTextColor(fg);info.setTextSize(14);info.setMaxLines(2);info.setEllipsize(TextUtils.TruncateAt.END);addView(info,new LayoutParams(0,-2,1));setContentDescription("Open Audio Mini");setOnClickListener(w->UtilityPopupManager.toggle(c,"audio"));}
 protected void onAttachedToWindow(){super.onAttachedToWindow();audio.add(this);changed();}
 protected void onDetachedFromWindow(){removeCallbacks(retry);audio.remove(this);super.onDetachedFromWindow();}
 public void changed(){boolean has=audio.displayable();info.setVisibility(has?VISIBLE:GONE);info.setText(has?audio.lines():"");setContentDescription(has?audio.lines()+". Open Audio Mini":"Open Audio Mini");int length=has?maxLength:DockController.px(getContext(),48);android.view.ViewGroup.LayoutParams p=getLayoutParams();if(p==null)return;if(touched.getAsBoolean()){removeCallbacks(retry);postDelayed(retry,100);return;}int beforeX=horizontal==null?0:horizontal.getScrollX(),beforeY=scroll==null?0:scroll.getScrollY();if(vertical){if(p.height==length)return;p.height=length;}else{if(p.width==length)return;p.width=length;}setLayoutParams(p);post(()->{if(horizontal!=null)horizontal.scrollTo(beforeX,0);if(scroll!=null)scroll.scrollTo(0,beforeY);});}
}
